#!/usr/bin/env python3
"""Build the public, sanitized Joyce business site. No client/private data input."""
from pathlib import Path
import ast, base64, csv, hashlib, html, json, re
ROOT=Path(__file__).resolve().parents[1]
J=ROOT/'joyce'
for d in ('assets','content','downloads','docs'): (J/d).mkdir(exist_ok=True)
e=html.escape
VERSION='2026-09-19-v2'
old=(J/'index.html').read_text()
catalogue=J/'content/capabilities.json'
if catalogue.exists(): caps=json.loads(catalogue.read_text())
else:
    m=re.search(r'const capabilities=(\[.*?\]);',old,re.S)
    if not m: raise RuntimeError('Cannot locate source capability data; refusing to erase content.')
    caps=ast.literal_eval(m.group(1))
    catalogue.write_text(json.dumps(caps,ensure_ascii=False,indent=2)+'\n')
with (J/'rate-card.csv').open(newline='',encoding='utf-8-sig') as f:
    rates=[r for r in csv.DictReader(f) if re.fullmatch(r'S\d{2}',r['ID'])]
assert len(rates)==16 and len(caps)==14
assert len({r['ID'] for r in rates})==16
for r in rates:
    r['fee']=int(r['CNY_base']); r['group']='ai' if r['ID'] in ('S13','S14') else 'partner' if r['ID'] in ('S10','S11','S12') else 'advisory'
(J/'content/services.json').write_text(json.dumps(rates,ensure_ascii=False,indent=2)+'\n')
b64=J/'assets/portrait-source.b64'
if b64.exists():
    raw=base64.b64decode(b64.read_text(),validate=False)
    if not (raw[:4]==b'RIFF' and raw[8:12]==b'WEBP'): raise ValueError('Portrait is not a WebP asset')
    (J/'assets/joyce-portrait.webp').write_bytes(raw)
if not (J/'assets/joyce-portrait.webp').exists(): raise FileNotFoundError('Approved photographic portrait required')

scenarios=[
('01','An operating question that will not go away','Unclear symptoms, inconsistent priorities, repeated ad-hoc requests.','A bounded decision session; assumptions, decision owner and follow-up scope.','S01'),
('02','A category or benchmark mismatch','The reference game, market or business model may not match the product.','A category-fit assessment and decision memo.','S02'),
('03','UA spend without a defensible growth case','Acquisition, retention and payback tell conflicting stories.','A read-only UA review with scoped commercial recommendations.','S05'),
('04','A product and its website tell different stories','Positioning, player proposition and commercial messaging do not align.','Product/positioning assessment and a prioritized brief.','S02 / S04'),
('05','The wrong role is being recruited','Title, seniority, responsibilities and evaluation criteria are unclear.','Role scorecards, JD calibration and an interview rubric.','S07'),
('06','An introduction without a fit case','A senior contact is requested before the purpose or value exchange is clear.','Partner research, a permission-based introduction brief and coordination.','S08'),
('07','A number looks persuasive but its definition does not','Annual versus cumulative; revenue versus profit; inconsistent currencies.','Source and metric-definition review for a bounded decision.','S01 / S09'),
('08','Adjacent game categories get treated as interchangeable','Social Casino, real-money products and machine-based gaming require distinct analysis.','Product/category and team-fit review; specialist questions where needed.','S02'),
('09','R&D is ready but the publishing layer is not','Markets, channels, launch ownership and commercial assumptions are disconnected.','A scoped publishing/GTM assessment or sprint.','S04'),
('10','The product ships but operating ownership disappears','Release, staffing and post-launch responsibilities are unclear.','Organization and handoff assessment; an operating mandate if required.','S07 / S11'),
('11','Metrics exist but commercial priorities do not','Data, economy and player lifecycle are reviewed in separate conversations.','A product, monetization or LiveOps review with agreed boundaries.','S03 / S06'),
('12','Expert access has become an unlimited inbox','Repeated advice has no scope, capacity ceiling or commercial agreement.','A prepaid, capacity-bounded advisory retainer and decision log.','S10')]
(J/'content/advisory-scenarios.json').write_text(json.dumps(scenarios,indent=2)+'\n')

